"""Generate publish/WORLD_COUNTS.md: per-country coverage across the global_municipalities country list."""
import csv, collections, os, json, glob, time
ROOT = "/workspace/world_courts"
GM = "/workspace/global_municipalities/global_municipalities_candidate.csv"
places = collections.Counter()
for x in csv.DictReader(open(GM)): places[x["country_code"]] += 1
TERRITORY_EXTRA = [d.upper() for d in os.listdir(f"{ROOT}/data") if len(d) == 2 and os.path.exists(f"{ROOT}/data/{d}/{d}_courthouses.jsonl") and d.upper() not in places]
for cc in TERRITORY_EXTRA: places[cc] += 0
def rows(cc, kind):
    f = f"{ROOT}/data/{cc.lower()}/{cc.lower()}_{kind}.jsonl"
    return [json.loads(l) for l in open(f)] if os.path.exists(f) else []
def nlines(cc, kind):
    fs = sorted(glob.glob(f"{ROOT}/data/{cc.lower()}/{cc.lower()}_{kind}*.jsonl")) if kind == "forms" else [f"{ROOT}/data/{cc.lower()}/{cc.lower()}_{kind}.jsonl"]
    return sum(1 for f in fs if os.path.exists(f) for _ in open(f))
out = []; tot = collections.Counter(); gaps = collections.defaultdict(list)
for cc in sorted(places):
    if not cc: continue
    ch = rows(cc, "courthouses")
    courthouses = [r for r in ch if r.get("record_type") == "courthouse"]; bodies = len(ch) - len(courthouses)
    j, ru, fo = nlines(cc, "judges"), nlines(cc, "rules"), nlines(cc, "forms")
    pl = sum(1 for r in courthouses if r.get("place_ids")); par = sum(1 for r in courthouses if r.get("parent_court_id")); wdn = sum(1 for r in courthouses if r.get("wikidata"))
    osmraw = f"{ROOT}/data/row/osm_{cc}.jsonl"
    if not ch: status = "none"
    elif not courthouses: status = "bodies only"
    else: status = "courthouses"
    g = []
    if status == "none": g.append("no data")
    if status == "bodies only": g.append("OpenStreetMap/Wikidata list no courthouse for this country")
    if courthouses and not j: g.append("judges")
    if courthouses and not ru: g.append("rules")
    if courthouses and not fo: g.append("forms")
    if courthouses and pl < 0.5 * len(courthouses): g.append("place links <50%")
    if courthouses and par < 0.7 * len(courthouses): g.append("tier unclassified >30%")
    if cc == "US":
        ch = [json.loads(l) for l in open(f"{ROOT}/data/us/us_courthouses.jsonl")]; bodies = sum(1 for r in ch if r.get("record_type") == "court_body"); ch = [r for r in ch if r.get("record_type") != "court_body"]; courthouses = ch
        j = nlines("us", "judges"); fo = nlines("us", "forms"); ru = sum(1 for f in glob.glob(f"{ROOT}/rules/out/us_rules_??.jsonl") for _ in open(f))
        pl = sum(1 for r in ch if r.get("place_ids")); par = sum(1 for r in ch if r.get("parent_court_id")); wdn = sum(1 for r in ch if r.get("wikidata")); status = "courthouses"
        g = ["court bodies are modelled only for SC circuits and VA judicial districts (record_type=court_body); elsewhere levels are carried on each courthouse row"]
    if cc in ("AN", "SU", "YU"): status = "obsolete code"; g = ["historical country code in global_municipalities; no current courts"]
    out.append((cc, places[cc], len(courthouses), bodies, pl, par, wdn, j, ru, fo, status, "; ".join(g)))
    for k, v in (("courthouses", len(courthouses)), ("bodies", bodies), ("judges", j), ("rules", ru), ("forms", fo), ("place_linked", pl)): tot[k] += v
    tot["countries"] += 1; tot["with_courthouses"] += status in ("courthouses", "US pipeline"); tot["with_judges"] += j > 0; tot["with_rules"] += ru > 0; tot["with_forms"] += fo > 0
now = time.strftime("%Y-%m-%d %H:%M %Z")
md = [f"# World courts: per-country coverage\n", f"Generated {now} from `data/<cc>/<cc>_*.jsonl` for every country code in `global_municipalities_candidate.csv` ({tot['countries']} codes).\n",
      "Columns: places = rows in global_municipalities for the country; courthouses/bodies = rows in `<cc>_courthouses.jsonl`; placed = courthouses with at least one `place_ids`; tiered = courthouses with a `parent_court_id`; wd = rows carrying a Wikidata id; judges/rules/forms = row counts.\n",
      f"## Totals\n", f"- Countries listed: {tot['countries']}; with courthouses: {tot['with_courthouses']}; with judge rosters: {tot['with_judges']}; with rules: {tot['with_rules']}; with forms: {tot['with_forms']}.",
      f"- Courthouse rows: {tot['courthouses']:,} ({tot['place_linked']:,} linked to a place id); court-body rows: {tot['bodies']:,}; judge rows: {tot['judges']:,}; rule rows: {tot['rules']:,}; form rows: {tot['forms']:,}.\n",
      "## Per country\n", "| cc | places | courthouses | bodies | placed | tiered | wd | judges | rules | forms | status | gaps |", "|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in out: md.append("| " + " | ".join(str(x) for x in r) + " |")
open(f"{ROOT}/publish/WORLD_COUNTS.md", "w").write("\n".join(md) + "\n")
nt = ["", "## Method and gaps", "- Courthouses for chunk 5 (137 countries and territories) come from OpenStreetMap `amenity=courthouse` (ODbL, one batched Overpass request per six countries) merged with Wikidata court items that have coordinates (CC0, 120 m dedupe). Four generic bodies per country (supreme / appeal / high / lower) are assigned by multilingual keyword classification; rows whose names do not indicate a tier have no `parent_court_id` and `needs_review=true`.",
 "- CK AI NR SM TC TV NU IO KY MS had no OSM courthouse and no Wikidata court with coordinates: their rows (1-3 each) come from official court pages plus a Nominatim/OSM position, all `needs_review=true` (`source_kind=official_page` or `osm`).",
 "- OSM noise (homes, farms, prosecutors, ministries, shops) is dropped with a name filter; ZW additionally drops 62 unclassifiable personal-plot rows. Names are not independently verified.",
 "- Wikidata (WDQS) was rate-limited (429/504) throughout; it added rows only for the countries listed in the `wd` column.",
 "- Depth pass 1 (2026-10-27): top-court rosters (leadership and, where published, members) for BD DE TR ID CN RU ET EG CD VN IR TH, all `needs_review=true`; EG, VN, IR and CD partly rely on news or Wikipedia excerpts (tagged in `site_policy`). Rules added for BD (CPC 1908, CrPC 1898 via a Wayback snapshot of bdlaws) and CN (Civil Procedure Law 2023 via cicc.court.gov.cn). Rules not obtained: ID (peraturan.bpk.go.id and mahkamahagung.go.id return 403), VN (vbpl.vn WAF block), RU (pravo.gov.ru and TH krisdika.go.th unreachable), ET, EG, CD, IR (no official machine-readable source found/probed). None bypassed.",
 "- Depth pass 2 (2026-10-27): top-court rosters for FR IT MM SD ES DZ AF (IT, SD, AF are minimal: leadership only; IT/DZ constitutional courts are mapped to the national apex body because no separate body row exists). Rules added for DZ (Loi 08-09 CPCA, 1,062 articles, JORADP), PK (Code of Criminal Procedure 1898, 273 sections from a government-hosted PDF; the Civil Procedure Code has no official host found) and TZ (Civil Procedure Code Cap. 33 sections, Attorney General's Office). Not obtained: IT (Normattiva serves articles through per-article AJAX calls, no bulk export), KR (law.go.kr needs an API key), UG (ULII opt-out), IQ, MM, SD, AF (no official machine-readable source found). None bypassed.",
 "- Depth pass 3 (2026-10-27): top-court rosters (needs_review=true; secondary or news sources for SA, YE, ML, AO Constitutional Court, MG, BF, MA Cour de cassation president; YE is the Aden government roster only) for PL MA UZ SA PE AO MZ YE VE MG BF ML (131 judges; constitutional courts without a body row are mapped to the national apex body). Rules added for MA (Code of Civil Procedure, 466 articles, adala.justice.gov.ma, Arabic pdftotext artifacts possible), VE (CPC 1990, 939 articles, suscerte.gob.ve copy of the Gaceta), AO (CPC, 1,495 articles, tribunalsupremo.ao), UZ (Civil Procedure Code, 434 articles, lex.uz English text that may lag amendments) and SA (Law of Civil Procedures, 242 articles, moj.gov.sa). Not obtained: PE (congreso.gob.pe robots disallow all), MG (assemblee-nationale.mg ai-train=no), BF (court site unreachable; natlex behind Cloudflare), MZ (no official copy found), ML, YE. US county/municipal courts added from official directories for CA (Judicial Council facility list, partial), IL (Office of the Illinois Courts), OH (Supreme Court of Ohio municipal court list, names only), WI (circuit clerk directory and the 2021 municipal court directory) and MO (Missouri Courts municipal division list, no street addresses). Not obtained: FL (flcourts.gov robots disallow all), MI (JS-only directory), NC and MN (403), AZ (no static directory). Forms retry with site-specific index pages added GA ID OR IN ND WA; still no forms: DC FL LA MA MI MO MT NH NY OK SC TN (robots disallow, 403/Cloudflare/Turnstile, JS-only pages, or unreachable). None bypassed.",
 "- Depth pass 4 (2026-10-27): US county/municipal courts for 8 more states (NJ, NE, CT, MD, IA, NM, IN, CO; +864 rows; skipped: FL robots, MI JS-only, NC/MN/KS 403, AZ/UT no usable static directory, KY JS-rendered); judge rosters for ZM KZ GT ZW KH SN BO TN RW BJ TD SY (66 rows, needs_review=true); rules for GT (635) and BJ (1,175) with crosswalks (BO/SN CPC PDFs are scans and skipped; PE robots, MG ai-train opt-out, RO 403/robots, KR/PH/FR unreachable, PK 403, NG unreachable); national forms for ES (36), PL (137), AT (2); TR, CL and UA yielded no usable forms from allowed static pages. Forms counting now globs {cc}_forms*.jsonl so CA 507 forms are included. No blocks bypassed.",
 "- Depth pass 5 (2026-10-27): (a) US county/municipal courts +379 rows for AR (district court departments, 184), OR (municipal and justice courts from the 2022 registry via Wayback, 142) and NV (justice and municipal courts, city and phone only, 53); skipped: NY (Cloudflare challenge), PA (JS-rendered, only an Allegheny-only open-data CSV), MS directory has no court addresses, TN (empty response), OK (no municipal directory), AL and LA (association lists, not official), GA/KY JS, plus earlier FL/MI/NC/MN/KS/AZ/UT blockers. (b) judge rosters for NE MW EC SO NL GN BI HT BE JO DO CZ (30 rows, needs_review=true; KP skipped for lack of a reliable source and RO skipped as robots-blocked, replaced by DO and CZ); rules for ID (KUHAP UU 20/2025, 336 of 369 articles; OCR gaps, Pasal 1 missing); blockers: IT normattiva JS, GH GhaLII Cloudflare, UG ULII ai-train opt-out, ET scan-only, TH/VN/RU/IR/KR unreachable, NP Nepali PDF not parsed. (c) national forms for SG, CZ, HU and HK; NO (robots disallow /globalassets/ and /contentassets/), PT (robots disallow /Portals/) and IE (robots disallow /docs/) skipped, DK and LT 403, LU links JS-only. (d) AU rules for WA (Rules of the Supreme Court 1971, 1,011) and SA (Uniform Civil Rules 2020, 1,077); Vic Supreme Court GCP Rules 2025 only on a JS site and the Federal Court Rules 2011 only behind a 403 or the JS Federal Register of Legislation, so not built; CA rules for NS (942), PE (804), SK (762), MB (641), NL (641) and the Federal Courts Rules (605, Justice Laws XML via Wayback); NB full text is on pages robots disallow and QC is JS, so not built. No blocks bypassed.",
 "- Depth pass 6 (2026-10-27, non-US): (a) top-court judge rosters for RO CU SS GR PT SE HU AZ AE BY HN TJ AT PG CH (26 rows, all needs_review=true; GR, AE, BY and SS from news or government releases; RO names from search excerpts of the robots-blocked iccj.ro page; KP skipped for lack of a reliable source). (b) rules for 8 more countries: CH (ZPO, StPO, BGG via Fedlex filestore, 991), IS (civil and criminal procedure acts via Wayback; althingi.is Cloudflare-challenged, 426), LU (NCPC, Legilux, 1,415), LI (ZPO, Lilex, 632), AE (Civil Procedure Code 2022 via Wayback; live portal Cloudflare-challenged, 288 of 338 articles), ZM (High Court Rules, Cap 27, 45 orders), BW (Rules of the High Court 2011, 80 orders), SC (Code of Civil Procedure, 311 sections); blockers: AT RIS and MX INEGI refuse TLS from the box, HU njt.hu JS-only, BH legalaffairs.gov.bh 403 with no archive copy, LT Cloudflare. (c) national forms for DE (justiz.de federal forms, 28), TT (45), GY (4), JM (1) and BB (registry applications, 3); BS files return HTTP 500, FJ shows a challenge page, justice.fr in maintenance. (d) FR courthouses from the DILA Annuaire de l'administration (873 court offices; 816 matched existing rows and enriched their sources, 57 added) and place-id back-fill (FR 5, DE 83); IN district sites (dcourts.gov.in) list no court complexes in a static page and time out intermittently, BR CNJ open data unreachable, MX INEGI DENUE unreachable and Wayback offline, so IN, BR and MX were not extended. No blocks bypassed.",
 "- Depth pass 7 (2026-10-27, non-US): fixed row_rules9 re-run duplication (merge per rule_set_id; CH stable at 991). (a) CZ rules from e-Sbírka open-data SPARQL (OSŘ 467, TŘ 451); DZ already covered (Loi 08-09); blockers: GR (ministryofjustice.gr 403, no full official text), IL (gov.il has only a 4-page excerpt of the 2018 Civil Procedure Regulations), JO (lob.gov.jo SPA, internal API not used), TN (justice.gov.tn errors; archived Arabic PDF has an unreadable font and OCR is unavailable), EG (cc.gov.eg JS app, IDSC portal in maintenance, archived PDF is a different decree). (b) top-court judges for UA TG SL LA HK RS PY NI KG BG SV DK FI NO SK (17 rows, needs_review). (c) forms for FI (26), SK (98), PH (41), NA (36) and BW; MW e-forms page yielded none. (d) courthouses: PL from dane.gov.pl teleadresowe (CC0; 377 courts, 363 matched, 14 added), JP from courts.go.jp district location pages (444 entries, 364 matched, 80 added), ES from the Generalitat open-data list of Spanish judicial organs (444 Tribunales de Instancia, Audiencias Provinciales and TSJ seats, linked by INE code). IT Giustizia map is JS-only; IN eCourts and MX INEGI still time out, BR CNJ reachable but no static unit list, Wayback availability API returns 500. No blocks bypassed.",
 "- Pass 8 (2026-10-29): US federal courts (198 bodies from uscourts.gov court links: Supreme Court, 13 circuits, 94 districts, 88 bankruptcy courts, CFC, CIT; ~600 courthouse/divisional addresses from court sites, Census-geocoded and deduped against OSM), 1,471 serving Article III judges from the FJC CSV export, 8,694 federal local rules (89 courts, 162 rule sets, world_courts only) and 761 state trial judges (DE, NE, WI, IA official static rosters). Caselaw gaps: real court bodies replace generic placeholders for HK MN KZ KG TJ TM UZ FJ PG WS TO VU SB KI TV NR PW FM MH CK NU (children, judges and crosswalks re-parented); new body files for MO TK AS GU MP NC PF WF NF PN; Special Court for Sierra Leone (historical) and its residual court; IN CESTAT body.",
 "- US county/municipal depth (2026-10-27): Texas OCA municipal-court directory, Washington AOC directory (county district + municipal courts), South Carolina Judicial Branch municipal directory and Virginia OES district-court directory were merged into `us_courthouses` (judge and clerk names are not stored). Blocked or unusable: NY (nycourts.gov Cloudflare challenge), NJ (njcourts.gov WAF 403), PA (interactive map only), OH (roster covers only a dozen mayor's courts), GA (portal list is paginated JS), CO and KS (no addresses published).",
 "- Judges, rules and forms exist only for the countries marked in the table; most of the world has courthouses and bodies only. Official legal portals were frequently unreachable, JS-only, behind Cloudflare, or carry AI-use restrictions (e.g. TanzLII, ULII), so no rules/forms were collected from them.",
 "- Territories with no standing court (e.g. IO) are recorded with the nearest published sitting location only; the `US` row is provided by the separate justicedao/US pipeline and is not rebuilt here."]
open(f"{ROOT}/publish/WORLD_COUNTS.md", "a").write("\n".join(nt) + "\n")
print(json.dumps(tot))
